xml.Script:
        clBlue   := '0000C8';
        clGreen  := '009600';
        clRed    := 'C80000';
        clPurple := '800080';
        clYellow := 'FFFF00';
        clWhite  := 'FFFFFF';
        clOrange := 'FF6000';
        clCyan   := '00FFFF';

        R := 0.6;
        H := R * sin(Pi / 6) * 2 / 3;
        sAngle := 2*Pi / 6;

        for i := 0 to 5 do begin
            x[i] := R * sin(sAngle * i);
            y[i] := R * cos(sAngle * i);
            ax[i] := sin(sAngle * i + sAngle/2);
            ay[i] := cos(sAngle * i + sAngle/2);
        end;

        D := x[1] * 2 / 3;
